/**
 * Bleed Engine v2 scoring — the seven invariants of the Backend Instruction "Bleed v2 Scoring" v0.1
 * §4, plus the session outputs of §3.4. Fixtures are generated by pick_echo_v0_1.py (synthetic
 * sessions); never edit them to make a test pass — regenerate with make_fixtures.py.
 */

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const B = require('../bleedV2');
const fixtures = require('./bleed_v2_session_fixtures_v0_1.json');
const { pyRound } = require('../py');

const P = Array.from({ length: 12 }, (_, i) => i + 1);
const sum = (o) => Object.values(o).reduce((a, b) => a + b, 0);

function combinations(arr, k) {
  if (k === 0) return [[]];
  return arr.flatMap((x, i) => combinations(arr.slice(i + 1), k - 1).map((c) => [x, ...c]));
}
function validStates() {
  const out = [];
  for (const k of [1, 2]) {
    for (const gs of combinations(Object.keys(B.GROUPS), k)) {
      const shown = gs.flatMap((g) => B.GROUPS[g]);
      for (const n of [0, 1, 2]) for (const pk of combinations(shown, n)) out.push([gs, pk]);
    }
  }
  return out;
}
const STATES = [...validStates(), [[], []]]; // 189 valid + the refusal

/** Seeded PRNG (mulberry32) so the bias test is reproducible. */
function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const sample = (r, arr, k) => { const a = arr.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a.slice(0, k); };

// ── §3.5 Exact integer units (gate G6) ────────────────────────────────────────

const X = require('../exact');

test('§3.5 the unit is derived from the config: 3/10 today, 3/50 with fallback Blue at 0.08', () => {
  assert.deepEqual(B.UNIT, { num: 3, den: 10 });
  assert.deepEqual(B.deriveUnit({ ...B.CONFIG, fb_blue: '2/25' }).unit, { num: 3, den: 50 });
  assert.deepEqual(B.PICK_U[1], { core: 30, green: 10, blue: 6, purple: 4, yellow: 4 });
  assert.deepEqual(B.FB_U[4], { core: 10, blue: 1 });
});

test('§3.5 a binary float in the config fails loud', () => {
  // Python str(Fraction(0.1)) — what a float 0.1 really is
  assert.throws(() => B.deriveUnit({ ...B.CONFIG, fb_blue: '3602879701896397/36028797018963968' }), /too fine.*2\^53/);
  assert.throws(() => B.deriveUnit({ ...B.CONFIG, fb_blue: 0.1 }), /must be a string/);
  assert.throws(() => B.deriveUnit({ ...B.CONFIG, green: '1/3.0' }), /not an exact decimal or fraction/);
});

test('§3.5 all 190 question states: 58, 44 or 0 units, and q4 in points', () => {
  for (const [l1, pk] of STATES) {
    const u = B.questionUnits(l1, pk);
    const total = P.reduce((a, p) => a + sum(u[p]), 0);
    assert.ok([0, 44, 58].includes(total), `${l1} ${pk}: ${total}`);
    for (const p of P) for (const b of B.BASKETS) assert.ok(Number.isInteger(u[p][b]));
    const ref = B.scoreQuestion(l1, pk);
    for (const p of P) assert.ok(Math.abs(ref[p] - B.toPoints(sum(u[p]))) < 1e-9);
  }
});

test('§3.5 / §10 test 19: 1,000 random sessions — every mandje, total, P12 and gekozen_aandeel equal an exact-fraction computation', () => {
  const c = Object.fromEntries(['X', 'FB_CORE', 'green', 'blue', 'purple', 'yellow', 'fb_blue'].map((k) => [k, X.parseFraction(B.CONFIG[k])]));
  const add = (a, b) => X.frac(a.n * b.d + b.n * a.d, a.d * b.d);
  const zero = X.frac(0n);
  const exactSession = (qs) => {                                       // independent: no units anywhere
    const v = Object.fromEntries(P.map((p) => [p, Object.fromEntries(B.BASKETS.map((b) => [b, zero]))]));
    for (const [l1, pk] of qs) {
      if (!l1.length) continue;
      if (pk.length) {
        const core = X.div(c.X, X.fromInt(pk.length));
        for (const x of pk) {
          v[x].keuze = add(v[x].keuze, core);
          v[B.sibling(x)].groen = add(v[B.sibling(x)].groen, X.mul(c.green, core));
          const bb = B.blue(x), k = B.groupOf[bb] === B.groupOf[x] ? 'blauw_intern' : 'blauw';
          v[bb][k] = add(v[bb][k], X.mul(c.blue, core));
          v[B.purple(x)].paars = add(v[B.purple(x)].paars, X.mul(c.purple, core));
          for (const y of B.yellow(x)) v[y].geel = add(v[y].geel, X.mul(c.yellow, core));
        }
      } else {
        const shown = l1.flatMap((g) => B.GROUPS[g]), core = X.div(c.FB_CORE, X.fromInt(shown.length));
        for (const x of shown) {
          v[x].passief = add(v[x].passief, core);
          const bb = B.blue(x), k = B.groupOf[bb] === B.groupOf[x] ? 'blauw_intern' : 'blauw';
          v[bb][k] = add(v[bb][k], X.mul(c.fb_blue, core));
        }
      }
    }
    return v;
  };
  const r = rng(11);
  const G = Object.keys(B.GROUPS);
  let ties = 0, halves = 0;
  for (let n = 0; n < 1000; n++) {
    const qs = [];
    for (let i = 0; i < 36; i++) {
      if (r() < 0.05) { qs.push([[], []]); continue; }
      const gs = sample(r, G, r() < 0.5 ? 1 : 2);
      qs.push([gs, sample(r, gs.flatMap((g) => B.GROUPS[g]), [0, 1, 1, 2][Math.floor(r() * 4)])]);
    }
    const u = B.testUnits(qs), e = exactSession(qs);
    const unit = X.frac(BigInt(B.UNIT.num), BigInt(B.UNIT.den));
    for (const p of P) {
      for (const b of B.BASKETS) { const v = X.mul(X.fromInt(u[p][b]), unit); assert.ok(v.n === e[p][b].n && v.d === e[p][b].d, `mandje ${p}.${b}`); }
      const tot = B.BASKETS.reduce((a, b) => add(a, e[p][b]), zero);
      assert.ok(X.mul(X.fromInt(sum(u[p])), unit).n === tot.n);
      // P12 in exact fractions
      let exactHerk = null;
      if (tot.n > 0n) {
        const echo = B.ECHO.reduce((a, b) => add(a, e[p][b]), zero);
        const twice = X.mul(echo, X.fromInt(2));
        if (twice.n * tot.d === tot.n * twice.d) ties++;
        exactHerk = twice.n * tot.d >= tot.n * twice.d ? 'echo'
          : (e[p].keuze.n * e[p].passief.d >= e[p].passief.n * e[p].keuze.d ? 'keuze' : 'passief');
      }
      assert.equal(B.supportHerkomst(u, p), exactHerk, `P12 ${p}`);
    }
    // gekozen_aandeel: exact half-up of 100 × gekozen / totaal
    const gv = B.groupView(u);
    for (const [g, ps] of Object.entries(B.GROUPS)) {
      const gek = ps.reduce((a, p) => add(add(a, e[p].keuze), e[p].passief), zero);
      const tot = ps.reduce((a, p) => B.BASKETS.reduce((s, b) => add(s, e[p][b]), a), zero);
      if (tot.n === 0n) { assert.equal(gv[g].gekozen_aandeel, 0); continue; }
      const pct = X.div(X.mul(gek, X.fromInt(100)), tot);                // exact percentage
      const twice = pct.n * 2n, den2 = pct.d * 2n;
      const halfUp = Number((twice + pct.d) / den2);                     // ⌊pct + 1/2⌋
      if ((pct.n * 2n) % pct.d === 0n && pct.d !== 1n) halves++;
      assert.equal(gv[g].gekozen_aandeel, halfUp, `gekozen_aandeel ${g}`);
    }
  }
  assert.ok(ties > 0, 'the run includes exact 50 % ties');
  assert.ok(halves > 0, 'the run includes exact .5 percentages');
});

// ── §4.1 Reference parity ─────────────────────────────────────────────────────

test('§4.1 the 190 question states: 189 valid + refusal; mandjes sum to q4 within 1e-9', () => {
  assert.equal(STATES.length, 190);
  for (const [l1, pk] of STATES) {
    const ref = B.scoreQuestion(l1, pk);
    const b = B.questionBaskets(l1, pk);
    for (const p of P) assert.ok(Math.abs(ref[p] - sum(b[p])) < 1e-9, `${l1} ${pk} @${p}`);
  }
});

test('§4.1 the spec value table (bleed_sim printout)', () => {
  const round = (v) => Object.fromEntries(Object.entries(v).filter(([, x]) => x > 0).map(([p, x]) => [B.byPos(+p), Math.round(x * 1000) / 1000]));
  assert.deepEqual(round(B.scoreQuestion(['Ruling'], [1, 12])),
    { Judge: 6.9, Innocent: 0.6, Explorer: 0.6, Outlaw: 0.6, Trickster: 0.6, Sage: 0.6, Artist: 0.6, Ruler: 6.9 });
  assert.deepEqual(round(B.scoreQuestion(['Relational', 'Seeker'], [2, 3])),
    { Lover: 6, Caregiver: 6, Outlaw: 0.6, Trickster: 0.6, Sage: 0.6, Artist: 0.6, Magician: 1.5, Hero: 1.5 });
  assert.deepEqual(round(B.scoreQuestion(['Ruling'], [])), { Judge: 6.6, Ruler: 6.6 });
  assert.deepEqual(round(B.scoreQuestion(['Relational', 'Seeker'], [])),
    { Lover: 3, Caregiver: 3, Innocent: 3, Explorer: 3, Sage: 0.3, Artist: 0.3, Magician: 0.3, Hero: 0.3 });
});

// ── §4.2 Fixtures ─────────────────────────────────────────────────────────────

for (const [name, c] of Object.entries(fixtures.cases)) {
  test(`§4.2 fixture ${name}: mandjes, group view and payload block`, () => {
    assert.equal(c.questions.length, 36);
    const acc = B.testBaskets(B.toScoringInput(c.questions));
    for (const [arch, exp] of Object.entries(c.expected.archetypes)) {
      const got = acc[B.posOf[arch]];
      // exactly as make_fixtures writes them: round(points, 4) — byte-identical under G6, no tolerance
      for (const k of B.BASKETS) assert.equal(pyRound(got[k], 4), exp[k], `${arch}.${k}`);
      assert.equal(pyRound(sum(got), 4), exp.totaal, `${arch}.totaal`);
    }
    assert.deepEqual(B.groupView(B.testUnits(B.toScoringInput(c.questions))), c.expected.groups);
    assert.equal(B.payloadBlock(B.testUnits(B.toScoringInput(c.questions))), c.expected.payload_block);
    const s = B.scoreSession(c.questions);
    assert.deepEqual(s.group_view, c.expected.groups);
    assert.equal(s.payload_block, c.expected.payload_block);
    const groupSum = Object.values(s.group_view).reduce((a, g) => a + g.totaal, 0);
    assert.ok(Math.abs(groupSum - sum(s.totals)) <= 0.1 + 1e-9, 'Σ group totals = Σ archetype totals (±0.1)');
  });
}

// ── §4.3 Per question ─────────────────────────────────────────────────────────

test('§4.3 per question: picks outrank non-picks, nothing above 9, totals only 17.4 / 13.2 / 0', () => {
  for (const [l1, pk] of STATES) {
    const v = B.scoreQuestion(l1, pk);
    const total = Math.round(sum(v) * 1000) / 1000;
    if (!l1.length) assert.equal(total, 0);
    else assert.equal(total, pk.length ? 17.4 : 13.2, `${l1} ${pk}`);
    assert.ok(Math.max(...Object.values(v)) <= 9 + 1e-9);
    if (pk.length) {
      const others = P.filter((p) => !pk.includes(p)).map((p) => v[p]);
      assert.ok(Math.max(...others) <= Math.min(...pk.map((p) => v[p])) + 1e-9, `a non-pick outranks a pick: ${l1} ${pk}`);
    }
  }
});

// ── §4.4 Group mass ───────────────────────────────────────────────────────────

test('§4.4 group mass: keuze + passief + groen = 12 per answered question, all inside the shown groups', () => {
  for (const [l1, pk] of validStates()) {
    const b = B.questionBaskets(l1, pk);
    const shown = new Set(l1.flatMap((g) => B.GROUPS[g]));
    let inside = 0;
    for (const p of P) {
      const mass = b[p].keuze + b[p].passief + b[p].groen;
      if (shown.has(p)) inside += mass;
      else assert.ok(mass < 1e-12, `group mass outside the shown groups: ${l1} ${pk} @${B.byPos(p)}`);
    }
    assert.ok(Math.abs(inside - 12) < 1e-9, `${l1} ${pk}: ${inside}`);
  }
});

// ── §4.5 Geometry ─────────────────────────────────────────────────────────────

test('§4.5 geometry: paars and geel never land in the pick\'s own group; blauw_intern only on Judge, Ruler, Outlaw, Trickster', () => {
  for (const p of P) assert.notEqual(B.groupOf[B.purple(p)], B.groupOf[p]);
  for (const p of P) for (const y of B.yellow(p)) assert.notEqual(B.groupOf[y], B.groupOf[p]);
  for (const [l1, pk] of validStates()) {
    const b = B.questionBaskets(l1, pk);
    const picked = new Set(pk.map((x) => B.groupOf[x]));
    for (const p of P) {
      if (b[p].blauw_intern) assert.ok(['Judge', 'Ruler', 'Outlaw', 'Trickster'].includes(B.byPos(p)));
      // only one pick per group can carry paars/geel into another picked group — never its own
      if (pk.length === 1 && picked.has(B.groupOf[p])) assert.equal(b[p].paars + b[p].geel, 0);
    }
  }
});

// ── §4.6 No bias ──────────────────────────────────────────────────────────────

test('§4.6 no bias: 3,000 random responders keep every archetype within ±1.0 % of the mean', () => {
  const r = rng(3);
  const G = Object.keys(B.GROUPS);
  const acc = Object.fromEntries(P.map((p) => [p, 0]));
  for (let i = 0; i < 3000 * 36; i++) {
    const gs = sample(r, G, r() < 0.5 ? 1 : 2);
    const shown = gs.flatMap((g) => B.GROUPS[g]);
    const pk = sample(r, shown, Math.floor(r() * 3));
    const v = B.scoreQuestion(gs, pk);
    for (const p of P) acc[p] += v[p];
  }
  const mean = sum(acc) / 12;
  for (const p of P) assert.ok(Math.abs(acc[p] / mean - 1) <= 0.01, `${B.byPos(p)} ${(100 * (acc[p] / mean - 1)).toFixed(2)} %`);
});

// ── §4.7 Fail loud ────────────────────────────────────────────────────────────

test('§4.7 fail loud: malformed response records throw, never coerced', () => {
  const ok = { l1_refusal: false, l1_groups: ['Relational'], l2_picks: ['Lover'] };
  const bad = [
    [null, /not a record/],
    [{ ...ok, l1_refusal: undefined }, /l1_refusal must be a boolean/],
    [{ ...ok, timeout: 'no' }, /timeout must be a boolean/],
    [{ l1_refusal: false, l2_picks: [] }, /missing l1_groups/],
    [{ l1_refusal: false, l1_groups: ['Relational'] }, /missing l2_picks/],
    [{ l1_refusal: true, l1_groups: ['Relational'], l2_picks: [] }, /refusal or timeout carries no/],
    [{ l1_refusal: false, timeout: true, l1_groups: [], l2_picks: ['Lover'] }, /refusal or timeout carries no/],
    [{ l1_refusal: false, l1_groups: [], l2_picks: [] }, /Layer 1 needs 1–2 groups/],
    [{ l1_refusal: false, l1_groups: ['Ruling', 'Chaos', 'Seeker'], l2_picks: [] }, /Layer 1 needs 1–2 groups/],
    [{ l1_refusal: false, l1_groups: ['Ruling', 'Ruling'], l2_picks: [] }, /duplicate Layer-1 group/],
    [{ l1_refusal: false, l1_groups: ['Nope'], l2_picks: [] }, /unknown group/],
    [{ l1_refusal: false, l1_groups: ['Ruling', 'Chaos'], l2_picks: ['Judge', 'Ruler', 'Outlaw'] }, /at most 2 picks/],
    [{ l1_refusal: false, l1_groups: ['Ruling'], l2_picks: ['Lover'] }, /outside the picked Layer-1 group/],
    [{ l1_refusal: false, l1_groups: ['Ruling'], l2_picks: ['Judge', 'Judge'] }, /duplicate Layer-2 pick/],
    [{ l1_refusal: false, l1_groups: ['Ruling'], l2_picks: ['Zeus'] }, /unknown archetype/],
  ];
  for (const [rec, re] of bad) assert.throws(() => B.scoreSession([ok, rec]), (e) => e instanceof B.BleedInputError && re.test(e.message) && e.index === 1, JSON.stringify(rec));
  assert.throws(() => B.scoreSession('nope'), B.BleedInputError);
  // the session store's shapes are accepted as-is: l1_picks [{group, slot}], l2_picks [{archetype}]
  const s = B.scoreSession([{ l1_refusal: false, l1_picks: [{ group: 'Relational', slot: 'C' }], l2_picks: [{ archetype: 'Lover' }] }]);
  assert.equal(s.main, 'Lover');
});

// ── §3.4 Session outputs ──────────────────────────────────────────────────────

test('§3.4 identity: Main, Support, Shadow, tetrad, single picks, polar_norm', () => {
  const s = B.scoreSession(fixtures.cases.ruling_tetrad.questions);
  assert.equal(s.scoring_version, 'v2_two_layer');
  assert.equal(s.main, 'Ruler');
  assert.equal(s.support, 'Judge');
  assert.equal(s.shadow, 'Outlaw');
  assert.equal(s.tetrad, true);
  assert.equal(s.single_picks.Ruler, 16);
  assert.equal(Math.round(s.polar_norm * 1000) / 1000, 0.77);          // addendum rev 2 table
  assert.equal(s.polarizationPct, 77);
  assert.equal(s.polarizationLevel, 'HIGH_POLARIZATION');
  const lover = B.scoreSession(fixtures.cases.concentrated_lover.questions);
  assert.equal(lover.tetrad, false);
  assert.equal(lover.main, 'Lover');
  assert.equal(lover.shadow, 'Sage');
});

test('§3.4 tie chain: total → single picks → keuze → passief → lower wheel position (logged)', () => {
  // Each step on its own, by position: 2 = Lover, 4 = Innocent.
  const flat = (o = {}) => Object.fromEntries(P.map((p) => [p, o[p] ?? 0]));
  const mand = (o = {}) => Object.fromEntries(P.map((p) => [p, { keuze: o[p]?.keuze ?? 0, passief: o[p]?.passief ?? 0 }]));
  const top = (totals, singles, acc) => B.rank(flat(totals), flat(singles), mand(acc)).order[0];
  assert.equal(top({ 2: 10, 4: 11 }), 4);                                                   // total
  assert.equal(top({ 2: 10, 4: 10 }, { 4: 1 }), 4);                                         // single picks
  assert.equal(top({ 2: 10, 4: 10 }, {}, { 4: { keuze: 1 } }), 4);                          // keuze
  assert.equal(top({ 2: 10, 4: 10 }, {}, { 4: { passief: 1 } }), 4);                        // passief
  const last = B.rank(flat({ 2: 10, 4: 10 }), flat(), mand());
  assert.equal(last.order[0], 2);                                                           // lower wheel position
  assert.ok(last.tieBreaks.some((t) => t.join() === 'Innocent,Lover'), 'the final-step tie is reported');
  // end to end: a perfect mirror inside Relational falls through to the wheel position
  const pick = (a) => ({ l1_refusal: false, l1_groups: ['Relational'], l2_picks: a });
  const s = B.scoreSession([pick(['Lover']), pick(['Caregiver'])]);
  assert.equal(s.main, 'Lover');
  assert.equal(s.support, 'Caregiver');
  assert.ok(s.tie_breaks.some((t) => t.join() === 'Caregiver,Lover'));
});

test('Support margin (owner, 17 Oct): within 9 % of the runner-up, the most direct points is the Support', () => {
  assert.deepEqual(B.SUPPORT_MARGIN.margin, [9, 100]);
  // order: Main 1, runner-up 2, then 3, 4. Totals in units; direct = keuze + passief.
  const pick = (totals, acc) => B.pickSupport([1, 2, 3, 4], totals, Object.fromEntries([1, 2, 3, 4].map((p) => [p, { keuze: 0, passief: 0, ...acc[p] }])));
  const T = { 1: 200, 2: 100, 3: 95, 4: 80 };
  assert.deepEqual(pick(T, { 2: { keuze: 20 }, 3: { keuze: 40 } }), { support: 3, byTotal: 2 });    // within, more direct
  assert.equal(pick(T, { 2: { keuze: 40 }, 3: { keuze: 30 } }).support, 2);                           // within, fewer direct
  assert.equal(pick(T, { 2: { keuze: 40 }, 3: { keuze: 40 } }).support, 2);                           // equal direct keeps the rank
  assert.equal(pick({ ...T, 3: 91 }, { 2: { keuze: 20 }, 3: { keuze: 40 } }).support, 3);             // exactly 91 % is within
  assert.equal(pick({ ...T, 3: 90 }, { 2: { keuze: 20 }, 3: { keuze: 40 } }).support, 2);             // 90 % is outside
  assert.equal(pick({ 1: 200, 2: 1000, 3: 909 }, { 2: {}, 3: { keuze: 1 } }).support, 2);            // 90.9 %: exact, no rounding up
  assert.equal(pick(T, { 2: { keuze: 20 }, 3: { passief: 30 } }).support, 3);                          // passief is a direct choice too
  assert.equal(pick(T, { 1: { keuze: 99 }, 2: { keuze: 20 } }).support, 2);                            // the Main never takes part
  // two candidates over the runner-up: the most direct wins; level with each other → the higher rank
  assert.equal(pick({ ...T, 4: 92 }, { 2: { keuze: 10 }, 3: { keuze: 30 }, 4: { keuze: 50 } }).support, 4);
  assert.equal(pick({ ...T, 4: 92 }, { 2: { keuze: 10 }, 3: { keuze: 50 }, 4: { keuze: 50 } }).support, 3);
  // end to end: Caregiver leads on total but is mostly echo; Hero lies within 9 % with twice the direct points
  const s = B.scoreSession(fixtures.cases.concentrated_lover.questions);
  assert.equal(s.support_by_total, 'Caregiver');
  assert.equal(s.support, 'Hero');
  assert.ok(100 * s.totals_u.Hero >= 91 * s.totals_u.Caregiver);
  assert.equal(s.support_herkomst, 'keuze');
  assert.equal(B.scoreSession(fixtures.cases.ruling_tetrad.questions).support_by_total, 'Judge');     // no one within: unchanged
});

test('§3.4 a refusal-only session scores zero and never throws', () => {
  const s = B.scoreSession(Array.from({ length: 36 }, () => ({ l1_refusal: true, l1_groups: [], l2_picks: [] })));
  assert.equal(sum(s.totals), 0);
  assert.equal(s.polar_norm, 0);
});
